// scripts/generate-art.ts
// Usage:
//   RELEASE_ID=9 npx tsx scripts/generate-art.ts                      ← batch all R9 cards
//   RELEASE_ID=9 NEW=1 npx tsx scripts/generate-art.ts                ← batch R9, skip if has art
//   RELEASE_ID=9 PICK=1 npx tsx scripts/generate-art.ts               ← persistent pick for R9
//   RELEASE_ID=9 START_ID=330 PICK=1 npx tsx scripts/generate-art.ts  ← pick from card 330
//   START_ID=316 PICK=1 npx tsx scripts/generate-art.ts               ← cross-release from 316
//   START_ID=316 NEW=1 PICK=1 npx tsx scripts/generate-art.ts         ← cross-release, skip if has art
import * as fs from 'fs';
import * as path from 'path';
import * as http from 'http';
import * as dotenv from 'dotenv';
import { exec } from 'child_process';
dotenv.config({ path: '.env.local' });

import { createClient } from '@supabase/supabase-js';
import { GoogleGenAI } from '@google/genai';

const supabase = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.SUPABASE_SERVICE_ROLE_KEY ?? process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!
);
const ai = new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY! });

const PICK_PORT = 3458;
const SAMPLES_DIR = path.join(process.cwd(), 'art-samples', 'generated');

