const r24Panda = (where: string, material: string) =>
  `Hidden easter egg: a tiny stuffed black-and-white panda with a big round head and large sparkly eyes is ${where}, rendered in the same tones as the surrounding ${material} so it blends in naturally. It occupies a very small area. It is NOT a subject — it is a hidden secret requiring careful inspection to find.`;
const r24Bunny = (where: string, material: string) =>
  `Hidden easter egg: a tiny sage-green stuffed bunny rabbit with floppy ears is ${where}, rendered in the same muted green tones as the surrounding ${material} so it blends in. It occupies a very small area. It is NOT a subject — it is a hidden secret requiring careful inspection to find.`;
const R22_STYLE = `Corporate Memphis flat design illustration — clean vector shapes, minimal color palette, friendly geometric figures, modern tech startup aesthetic, bold simple composition`;
const R23_STYLE = `Vintage Olympic Games poster illustration (1936–1948 style) — heroic silhouette, limited warm palette, monumental composition, timeless athletic grandeur`;

const SUFFIX = `Square 1:1 format, fill the entire frame edge to edge with no borders or empty margins, no text or letters anywhere in the image.`;

function panda(location: string, context: string) {
  return `Hidden easter egg: a tiny stuffed panda is ${location}. It is rendered in the same tones as the surrounding ${context} so it blends in. It occupies a very small area. It is NOT a subject — it is a hidden secret that requires careful inspection to find.`;
}

function bunny(location: string, context: string) {
  return `Hidden easter egg: a tiny all-aqua stuffed bunny is ${location}. It is rendered in the same tones as the surrounding ${context} so it blends in. It occupies a very small area. It is NOT a subject — it is a hidden secret that requires careful inspection to find.`;
}

