type CardEntry = { id: number; name: string; prompt: string; releaseNum: number; dbReleaseId: number };

function getAllPrompts(): CardEntry[] {
  return Object.entries(PROMPTS_BY_RELEASE)
    .sort(([a], [b]) => parseInt(a) - parseInt(b))
    .flatMap(([num, entry]) =>
      entry.prompts.map(p => ({ ...p, releaseNum: parseInt(num), dbReleaseId: entry.dbReleaseId }))
    );
}

// ── Core generation ───────────────────────────────────────────────────────

async function generateImage(prompt: string, attempt = 1): Promise<Buffer> {
  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: [{ role: 'user', parts: [{ text: prompt }] }],
    config: { responseModalities: ['IMAGE', 'TEXT'] } as any,
  });
  const parts = response.candidates?.[0]?.content?.parts ?? [];
  const imagePart = parts.find((p: any) => p.inlineData?.mimeType?.startsWith('image/'));
  if (!imagePart?.inlineData?.data) {
    if (attempt >= 3) throw new Error('No image returned after 3 attempts');
    console.log(`  No image returned — retrying (attempt ${attempt + 1}/3)...`);
    await new Promise(r => setTimeout(r, 3000 * attempt));
    return generateImage(prompt, attempt + 1);
  }
  return Buffer.from(imagePart.inlineData.data, 'base64');
}

async function uploadCard(card: CardEntry, buffer: Buffer): Promise<void> {
  const outDir = `./art-output/release-${card.releaseNum}`;
  fs.mkdirSync(outDir, { recursive: true });
  const localPath = path.join(outDir, `${card.id}-${card.name.replace(/[^a-z0-9]/gi, '-')}.png`);
  fs.writeFileSync(localPath, buffer);
  console.log(`  Saved: ${localPath}`);

  const storagePath = `cards/release-${card.releaseNum}/${card.id}.png`;
  const { error: uploadError } = await supabase.storage
    .from('card-art')
    .upload(storagePath, buffer, { contentType: 'image/png', upsert: true });
  if (uploadError) throw uploadError;

  const { data: urlData } = supabase.storage.from('card-art').getPublicUrl(storagePath);
  const { error: dbError } = await supabase
    .from('cards')
    .update({ art_url: urlData.publicUrl })
    .eq('id', card.id);
  if (dbError) throw dbError;

  console.log(`  ✓ ${card.name} uploaded + DB updated`);
}

async function generateAndUpload(card: CardEntry): Promise<void> {
  console.log(`Generating: ${card.name} (id=${card.id})`);
  const buffer = await generateImage(card.prompt);
  await uploadCard(card, buffer);
}

