  if(!p)return;
  document.getElementById('overlay').classList.remove('show');
  fetch('/regenerate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt:p})});
  document.getElementById('app').innerHTML='<div class="center"><div class="spinner"></div><h2>Regenerating...</h2></div>';
  sel=null;lastTs=null;
