type CardDbAttrs = {
  type: string;
  value: number | null;
  operator: string | null;
  effect_type: string | null;
  effect_text: string | null;
  flavor_text: string | null;
};

async function runPickServer(queue: CardEntry[]): Promise<void> {
  if (queue.length === 0) {
    console.log('No cards to pick — queue is empty.');
    return;
  }

  // Pre-fetch card attributes for display in the picker UI
  const cardIds = queue.map(c => c.id);
  const { data: cardRows } = await supabase
    .from('cards')
    .select('id, type, value, operator, effect_type, effect_text, flavor_text')
    .in('id', cardIds);
  const cardDbMap = new Map<number, CardDbAttrs>(
    (cardRows ?? []).map(r => [r.id, r as CardDbAttrs])
  );

  let idx = 0;
  let serverState: {
    status: 'generating' | 'ready' | 'uploading' | 'regenerating' | 'complete';
    card: CardEntry | null;
    ts: string;
    imagePaths: string[];
  } = { status: 'generating', card: queue[0], ts: '', imagePaths: [] };

  // Preload queue — up to 2 cards ahead, running concurrently
  type PreloadEntry = { cardIdx: number; promise: Promise<{ ts: string; imagePaths: string[] }> };
  const preloads: PreloadEntry[] = [];

  async function generateImagesFor(card: CardEntry, tag: string, overridePrompt?: string): Promise<{ ts: string; imagePaths: string[] }> {
    const prompt = overridePrompt ?? card.prompt;
    const ts = `${card.id}-${Date.now()}`;
    const outDir = path.join(SAMPLES_DIR, ts);
    fs.mkdirSync(outDir, { recursive: true });
    const paths: string[] = [];
    for (let i = 1; i <= 3; i++) {
      console.log(`  [${tag}] [${i}/3] Generating...`);
      const buf = await generateImage(prompt);
      const fp = path.join(outDir, `${i}.png`);
      fs.writeFileSync(fp, buf);
      paths.push(fp);
      console.log(`  [${tag}] [${i}/3] ✓`);
      if (i < 3) await new Promise(r => setTimeout(r, 1500));
    }
    return { ts, imagePaths: paths };
  }

  function startPreload(nextIdx: number): void {
    if (nextIdx >= queue.length) return;
    if (preloads.some(p => p.cardIdx === nextIdx)) return; // already in flight
    const next = queue[nextIdx];
    console.log(`\n[preload] Starting: ${next.name} (id=${next.id})`);
    const entry: PreloadEntry = {
      cardIdx: nextIdx,
      promise: generateImagesFor(next, `preload ${next.name}`).catch(err => {
        console.error(`[preload] Failed for ${next.name}:`, err);
        const i = preloads.indexOf(entry);
        if (i !== -1) preloads.splice(i, 1);
        return { ts: '', imagePaths: [] };
      }),
    };
    preloads.push(entry);
  }

  async function generateCurrent(): Promise<void> {
    if (idx >= queue.length) {
      serverState = { status: 'complete', card: null, ts: '', imagePaths: [] };
      console.log('\nAll cards done! Press Ctrl+C to exit.');
      return;
    }
    const card = queue[idx];
    serverState = { status: 'generating', card, ts: '', imagePaths: [] };

    let result: { ts: string; imagePaths: string[] } | null = null;

    try {
      const preloadIdx = preloads.findIndex(p => p.cardIdx === idx);
      if (preloadIdx !== -1) {
        // Preload already started (or done) — just await it
        console.log(`\nAwaiting preloaded: ${card.name} (id=${card.id}, R${card.releaseNum})`);
        result = await preloads[preloadIdx].promise;
        preloads.splice(preloadIdx, 1);
        // If the preload returned empty paths (error fallback), regenerate fresh
        if (result.imagePaths.length === 0) {
          console.log(`  Preload had no images — regenerating fresh`);
          result = await generateImagesFor(card, card.name);
        }
      } else {
        // No preload for this card — generate synchronously
        console.log(`\nGenerating 3 variations of: ${card.name} (id=${card.id}, R${card.releaseNum})`);
        result = await generateImagesFor(card, card.name);
      }
    } catch (err) {
      console.error(`\nFailed to generate ${card.name} after all retries — skipping.`);
      console.error(err);
      idx++;
      generateCurrent().catch(console.error);
      return;
    }

    serverState = { status: 'ready', card, ts: result.ts, imagePaths: result.imagePaths };
    console.log(`Ready — pick in browser: http://localhost:${PICK_PORT}`);

    // Kick off the next 2 cards in the background while the user reviews this one
    startPreload(idx + 1);
    startPreload(idx + 2);
  }

  // Start generating first card immediately, preload second card in background
  generateCurrent().catch(console.error);

  const server = http.createServer((req, res) => {
    if (req.method === 'GET' && req.url === '/') {
      res.writeHead(200, { 'Content-Type': 'text/html' });
      res.end(PICK_HTML);
      return;
    }

    if (req.method === 'GET' && req.url === '/api/state') {
      res.writeHead(200, { 'Content-Type': 'application/json' });
      const cardAttrs = serverState.card ? cardDbMap.get(serverState.card.id) ?? null : null;
      res.end(JSON.stringify({
        status: serverState.status,
        card: serverState.card
          ? { id: serverState.card.id, name: serverState.card.name, releaseNum: serverState.card.releaseNum, prompt: serverState.card.prompt, attrs: cardAttrs }
          : null,
        ts: serverState.ts,
        queuePos: idx + 1,
        queueTotal: queue.length,
      }));
      return;
    }

    if (req.method === 'GET' && req.url?.startsWith('/img/')) {
      const parts = req.url.slice(5).split('/');
      const fp = path.join(SAMPLES_DIR, parts[0], parts[1]);
      if (fs.existsSync(fp)) {
        res.writeHead(200, { 'Content-Type': 'image/png' });
        res.end(fs.readFileSync(fp));
      } else {
        res.writeHead(404); res.end();
      }
      return;
    }

    if (req.method === 'POST' && req.url === '/select') {
      let body = '';
      req.on('data', c => { body += c; });
      req.on('end', async () => {
        const { sample } = JSON.parse(body);
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ ok: true }));

        const card = serverState.card!;
        const imagePaths = serverState.imagePaths;
        serverState = { ...serverState, status: 'uploading' };

        console.log(`\nSelected variation ${sample} — uploading ${card.name}...`);
        try {
          const buf = fs.readFileSync(imagePaths[sample - 1]);
          await uploadCard(card, buf);
        } catch (e) {
          console.error('Upload error:', e);
        }

        idx++;
        generateCurrent().catch(console.error);
      });
      return;
    }

    if (req.method === 'POST' && req.url === '/skip') {
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ ok: true }));
      console.log(`\nSkipping ${serverState.card?.name ?? '(unknown)'}`);
      idx++;
      generateCurrent().catch(console.error);
      return;
    }

    if (req.method === 'POST' && req.url === '/regenerate') {
      let body = '';
      req.on('data', c => { body += c; });
      req.on('end', async () => {
        const { prompt } = JSON.parse(body);
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ ok: true }));

        const card = { ...serverState.card!, prompt };
        serverState = { ...serverState, status: 'regenerating' };
        console.log(`\nRegenerating: ${card.name} (id=${card.id})...`);

        try {
          const result = await generateImagesFor(card, `regen ${card.name}`, prompt);
          serverState = { status: 'ready', card, ts: result.ts, imagePaths: result.imagePaths };
          console.log(`Regenerated — pick in browser: http://localhost:${PICK_PORT}`);
        } catch (err) {
          console.error(`Regeneration failed for ${card.name}:`, err);
          // Restore ready state with whatever images were previously shown
          serverState = { ...serverState, status: 'ready' };
        }
      });
      return;
    }

    res.writeHead(404); res.end();
  });

  server.listen(PICK_PORT, '127.0.0.1', () => {
    exec(`open "http://localhost:${PICK_PORT}"`);
    console.log(`\nBrowser picker → http://localhost:${PICK_PORT}`);
    console.log('Press Ctrl+C to stop.\n');
  });

  // Keep the process alive indefinitely
  await new Promise<never>(() => {});
}

// ── Main ──────────────────────────────────────────────────────────────────

async function main() {
  if (!process.env.GEMINI_API_KEY) { console.error('GEMINI_API_KEY not set in .env.local'); process.exit(1); }

  const hasReleaseId = !!process.env.RELEASE_ID;
  const releaseNum   = hasReleaseId ? parseInt(process.env.RELEASE_ID!, 10) : null;
  const startId      = process.env.START_ID ? parseInt(process.env.START_ID, 10) : null;
  const newOnly      = process.env.NEW === '1';
  const isPick       = process.env.PICK === '1';

  // ── No RELEASE_ID — cross-release mode (requires START_ID) ──────────────
  if (!hasReleaseId) {
    if (!startId) {
      console.error('Usage: RELEASE_ID=N [START_ID=X] [PICK=1] [NEW=1] npx tsx scripts/generate-art.ts');
      console.error('       or: START_ID=X PICK=1 [NEW=1] npx tsx scripts/generate-art.ts  (cross-release)');
      console.error(`Releases with prompts: ${Object.keys(PROMPTS_BY_RELEASE).join(', ')}`);
      process.exit(1);
    }

    let queue = getAllPrompts();
    const startIdx = queue.findIndex(p => p.id === startId);
    if (startIdx === -1) {
      console.error(`START_ID=${startId} not found in any release prompts`);
      process.exit(1);
    }
    queue = queue.slice(startIdx);

    if (newOnly) {
      const { data: existing } = await supabase.from('cards').select('id').not('art_url', 'is', null);
      const doneIds = new Set((existing ?? []).map((c: any) => c.id));
      const before = queue.length;
      queue = queue.filter(p => !doneIds.has(p.id));
      console.log(`Cross-release: ${queue.length} cards to pick (skipped ${before - queue.length} with existing art)`);
    } else {
      console.log(`Cross-release: ${queue.length} cards from id=${startId} onward`);
    }

    await runPickServer(queue);
    return;
  }

  // ── RELEASE_ID provided ──────────────────────────────────────────────────
  const entry = PROMPTS_BY_RELEASE[releaseNum!];
  if (!entry) {
    const valid = Object.keys(PROMPTS_BY_RELEASE).join(', ');
    console.error(`No prompts for RELEASE_ID=${releaseNum}. Releases with prompts: ${valid}`);
    process.exit(1);
  }

  const startIdx = startId ? entry.prompts.findIndex(p => p.id === startId) : 0;
  if (startId && startIdx === -1) {
    console.error(`START_ID=${startId} not found in R${releaseNum} prompts`);
    process.exit(1);
  }

  let cards: CardEntry[] = entry.prompts.slice(startIdx).map(p => ({
    ...p,
    releaseNum: releaseNum!,
    dbReleaseId: entry.dbReleaseId,
  }));

  if (newOnly) {
    const { data: existing } = await supabase
      .from('cards').select('id').eq('release_id', entry.dbReleaseId).not('art_url', 'is', null);
    const doneIds = new Set((existing ?? []).map((c: any) => c.id));
    const before = cards.length;
    cards = cards.filter(p => !doneIds.has(p.id));
    console.log(`R${releaseNum}: ${cards.length} cards (skipped ${before - cards.length} with existing art)`);
  }

  // ── PICK mode ────────────────────────────────────────────────────────────
  if (isPick) {
    await runPickServer(cards);
    return;
  }

  // ── Batch mode ───────────────────────────────────────────────────────────
  console.log(`\nR${releaseNum}: generating ${cards.length} cards\n`);
  for (const card of cards) {
    await generateAndUpload(card);
    await new Promise(r => setTimeout(r, 1500));
  }
  console.log('\nAll done!');
}

main().catch(console.error);
